import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        n = int(next(iterator))
        k = int(next(iterator))
        s = next(iterator)

        half_k = k // 2

        fixed = {}
        possible = True

        for i in range(n):
            if s[i] != '?':
                val = int(s[i])
                mod = i % k
                if mod in fixed:
                    if fixed[mod] != val:
                        possible = False
                        break
                else:
                    fixed[mod] = val

        if not possible:
            results.append("NO")
            continue

        count0 = 0
        count1 = 0
        for mod in range(k):
            if mod in fixed:
                if fixed[mod] == 0:
                    count0 += 1
                else:
                    count1 += 1

        if count0 > half_k or count1 > half_k:
            results.append("NO")
        else:
            results.append("YES")

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    solve()
